import { randomUUID } from "node:crypto";

import { index, integer, pgTable, serial, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { accounts } from "./accounts.js";

// Invoice ids are generated by the application.
export const invoices = pgTable("invoices", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => randomUUID()),
  accountId: uuid("account_id")
    .notNull()
    .references(() => accounts.id),
  total: integer("total").notNull(),
  status: text("status").notNull().default("draft"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

// Ledger postings of finalized invoices. No unique constraint on invoice_id.
export const postings = pgTable("postings", {
  id: serial("id").primaryKey(),
  invoiceId: text("invoice_id")
    .notNull()
    .references(() => invoices.id),
  amount: integer("amount").notNull(),
  postedAt: timestamp("posted_at", { withTimezone: true }).notNull().defaultNow(),
});

// Scheduled invoice runs, looked up by run key; the index is not unique.
export const invoiceRuns = pgTable(
  "invoice_runs",
  {
    id: serial("id").primaryKey(),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id),
    runKey: text("run_key").notNull(),
    period: text("period").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("invoice_runs_run_key").on(t.runKey)],
);

// Export jobs: the job key is the primary key.
export const exportJobs = pgTable("export_jobs", {
  jobKey: text("job_key").primaryKey(),
  accountId: uuid("account_id")
    .notNull()
    .references(() => accounts.id),
  format: text("format").notNull(),
  requestedAt: timestamp("requested_at", { withTimezone: true }).notNull().defaultNow(),
});
